# 핵심 자세 5장 동시에 (edit-images-v2, 장당 10)
import threading
from pl import edit
T=" Keep the exact same character design, face, colors, long black hair, dark coat with gold trim, gold shoulder armor, red-lined cape, size and the sword, full body, no effects, same facing direction."
JOBS={
 'key_walk_r':('src_walk_r.png',"Brisk long-stride walking pose, side view facing right, mid-stride contact: the front leg steps far forward with the heel touching the ground and the knee almost straight, the rear leg is far behind pushing off from the toes, a wide gap between the feet (about half of the body height), hips level, torso upright and slightly forward, the arm swings opposite to the legs, the sword held low in the right hand."+T),
 'key_walk_d':('src_walk_d.png',"Brisk long-stride walking pose toward the viewer, straight front view, face visible, mid-stride contact: his RIGHT leg (on the left side of the image) steps far forward toward the viewer with the heel touching the ground, that foot clearly lower in the image and slightly bigger; his LEFT leg is far behind, knee bent, standing on the toes, that foot clearly higher in the image. Feet about hip width apart, not crossed. Hips level, torso upright, arms swing opposite to the legs, the sword held low in the right hand."+T),
 'key_walk_u':('src_idle_u.png',"Brisk long-stride walking pose walking AWAY from the viewer, STRICT three-quarter BACK view toward the upper right, the face is not visible, we see his back, long hair and cape: the leg farther from the viewer steps far forward away from the viewer with the heel down, the leg nearer the viewer is far behind with the heel lifted so we see the sole of the boot, a wide gap between the feet, not crossed; arms swing opposite to the legs, the sword held low in the right hand at his side."+T),
 'key_run_d':('src_run_d.png',"Full-speed sprinting pose toward the viewer, straight front view, face visible: his RIGHT knee (on the left side of the image) drives high up and forward toward the viewer, thigh raised, foot off the ground under the knee; his LEFT leg pushes off far behind, nearly straight, only the toes touching the ground, that foot higher in the image. Torso leaning forward, arms pump opposite to the legs at his sides, neither hand raised above the chest, the sword in the right hand pointing down and back."+T),
 'key_run_u':('src_run_u.png',"Full-speed sprinting pose running AWAY from the viewer, STRICT three-quarter BACK view toward the upper right, the face is never visible, flight phase: the far leg drives forward and up away from the viewer, the near leg is extended far behind with the heel kicked up showing the sole of the boot, a long stride, torso leaning forward, the sword clearly visible held in the right hand pointing forward and down, hair and cape streaming back."+T),
}
ts=[threading.Thread(target=edit,args=(s,k+'.png',p,7)) for k,(s,p) in JOBS.items()]
[t.start() for t in ts];[t.join() for t in ts]
